// Neue, abgeschlossene Ausführungen von ALLY 1: Tokens aller KI-Modell-Läufe zusammenzählen.
// Die Liste kommt seitenweise (neueste zuerst), bis die zuletzt erfasste Ausführung erreicht ist.
// Laufende Ausführungen halten den Stand zurück, damit sie beim nächsten Mal erfasst werden.
// Mit Caching (Einstellung im KI-Knoten) gilt je Nachricht: der erste Aufruf schreibt den Zwischenspeicher,
// jeder weitere liest den Teil des vorigen Aufrufs und schreibt nur das Neue. n8n meldet nur die Summe je Aufruf,
// daher ist diese Aufteilung eine Schätzung (Treffer aus früheren Nachrichten sind nicht berücksichtigt).
const st = $('Stand laden').first().json;
const letzte = Number(st.letzte || 0);
const liste = $input.all().flatMap(i => i.json.data || []);
const fertig = ['success', 'error', 'crashed', 'canceled'];
const neu = liste.filter(e => Number(e.id) > letzte && fertig.includes(e.status));
const offen = liste.filter(e => Number(e.id) > letzte && !fertig.includes(e.status));
let bis = neu.reduce((m, e) => Math.max(m, Number(e.id)), letzte);
if (offen.length) bis = Math.min(bis, Math.min(...offen.map(e => Number(e.id))) - 1);
return neu.filter(e => Number(e.id) <= bis).sort((a, b) => Number(a.id) - Number(b.id)).map(e => {
  const rd = ((e.data || {}).resultData || {}).runData || {};
  const aufrufe = [];
  for (const laeufe of Object.values(rd)) {
    for (const r of laeufe || []) {
      const t = (((((r || {}).data || {}).ai_languageModel || [[]])[0] || [])[0] || {}).json?.tokenUsage;
      if (!t) continue;
      const opt = (((((r.inputOverride || {}).ai_languageModel || [[]])[0] || [])[0] || {}).json || {}).options || {};
      const cache = !!((opt.invocation_kwargs || {}).cache_control);
      aufrufe.push({ i: Number(r.executionIndex || 0), ein: Number(t.promptTokens || 0), aus: Number(t.completionTokens || 0), cache });
    }
  }
  aufrufe.sort((a, b) => a.i - b.i);
  let ein = 0, cs = 0, cl = 0, aus = 0, vorher = 0;
  for (const a of aufrufe) {
    aus += a.aus;
    if (a.cache) {
      const gelesen = Math.min(vorher, a.ein);
      cl += gelesen;
      cs += a.ein - gelesen;
      vorher = a.ein;
    } else {
      ein += a.ein;
      vorher = 0;
    }
  }
  const eing = (rd['6_4_eingang_zusammenfuehren'] || [])[0] || {};
  const sender = (((((eing.data || {}).main || [[]])[0] || [])[0] || {}).json || {}).sender || '';
  return { json: { ausfuehrung: 'n8n:' + e.id, zeit: e.startedAt, sender, modell: st.modell, ein, cs, cl, aus, bis: String(bis) } };
});
